-- ============================================
-- LUMA — Thème 16 : MOYEN 1/3 x4 — Un entretien pour un job de serveur à Sydney
-- ============================================


update scenarios set content = '{"characters": {"manager": "le gérant du restaurant"}, "start_node": "n1", "nodes": {"n1": {"speaker": "manager", "text": "Have you got your RSA certificate? We can''t hire without it for a bar role.", "text_fr": "Vous avez votre certificat RSA ? On ne peut pas embaucher sans ça pour un poste de bar.", "choices": [{"text": "Yes, I got it last week online, here''s the certificate.", "text_fr": "Oui, je l''ai obtenu la semaine dernière en ligne, voici le certificat.", "next": "n2"}, {"text": "Not yet, but I can get it done this week if needed.", "text_fr": "Pas encore, mais je peux le faire cette semaine si nécessaire.", "next": "n2b"}]}, "n2": {"speaker": "manager", "text": "Perfect, that''s sorted then. What''s your availability like?", "text_fr": "Parfait, c''est réglé alors. Vos disponibilités sont comment ?", "choices": [{"text": "I''m free every day, very flexible with my schedule.", "text_fr": "Je suis libre tous les jours, très flexible avec mon emploi du temps.", "next": "n3"}]}, "n2b": {"speaker": "manager", "text": "Alright, get that sorted and come back — I like your attitude though.", "text_fr": "D''accord, réglez ça et revenez — j''aime bien votre attitude cependant.", "choices": [{"text": "I''ll have it done by Friday, thank you for the chance.", "text_fr": "Je l''aurai fait d''ici vendredi, merci pour la chance.", "next": "n3"}]}, "n3": {"speaker": "manager", "text": "Great, that flexibility is exactly what we need for weekend shifts.", "text_fr": "Parfait, cette flexibilité est exactement ce qu''il nous faut pour les shifts du week-end.", "choices": [{"text": "Happy to help wherever needed.", "text_fr": "Content d''aider où besoin.", "next": "n4"}, {"text": "Do you have any experience requirements for the role?", "text_fr": "Vous avez des exigences d''expérience pour le poste ?", "next": "n4"}]}, "n4": {"speaker": "manager", "text": "Some hospitality experience helps, but honestly, attitude matters more to us.", "text_fr": "Un peu d''expérience en hôtellerie aide, mais honnêtement, l''attitude compte plus pour nous.", "choices": [{"text": "That''s reassuring, I worked in a café back home for a year.", "text_fr": "Ça rassure, j''ai travaillé dans un café chez moi pendant un an.", "next": "n5"}]}, "n5": {"speaker": "manager", "text": "Perfect background for this then. When could you start if we offered you the job?", "text_fr": "Parfait comme parcours pour ça alors. Vous pourriez commencer quand si on vous offrait le poste ?", "choices": [{"text": "As soon as you need me, I''m ready to start right away.", "text_fr": "Dès que vous avez besoin de moi, je suis prêt à commencer tout de suite.", "next": "n6"}]}, "n6": {"speaker": "manager", "text": "Great, that''s exactly what we need with the holiday season coming up.", "text_fr": "Parfait, c''est exactement ce qu''il nous faut avec la saison des fêtes qui arrive.", "choices": [{"text": "I''m excited about the opportunity, thank you for considering me.", "text_fr": "Je suis ravi de cette opportunité, merci de me considérer.", "next": "n7"}]}, "n7": {"speaker": "manager", "text": "Welcome to the team, we''ll start you on Saturday.", "text_fr": "Bienvenue dans l''équipe, vous commencez samedi.", "choices": [{"text": "Thank you so much, I won''t let you down!", "text_fr": "Merci beaucoup, je vais pas vous décevoir !", "next": "end_hired"}]}, "end_hired": {"speaker": "manager", "text": "I''m sure you won''t. See you Saturday!", "text_fr": "Je suis sûr que non. À samedi !", "end": true, "ending_label": "Job de serveur obtenu à Sydney 🍽️🇦🇺"}}}'::jsonb, is_playable = true
where title = 'Un entretien pour un job de serveur à Sydney'
  and theme_id = (select id from scenario_themes where position = 16 and language_id = (select id from languages where code = 'en'));
